# loading/eval

def parse_and_run(text, env, source='(string)', args=None):
    global CURRENT_SOURCE
    old=CURRENT_SOURCE; CURRENT_SOURCE=source
    try:
        block=Parser(text, source).parse()
        if args is not None: env.varargs=args
        exec_block(block, env)
        return []
    except ReturnSignal as r:
        return r.values
    finally:
        CURRENT_SOURCE=old

@bf('load')
def b_load(args):
    chunk=arg(args,0); chunkname=arg(args,1,'=(load)')
    if isinstance(chunk, str):
        text=chunk
    elif isinstance(chunk,(BuiltinFunction,UserFunction)):
        parts=[]
        while True:
            r=call_lua(chunk, [])
            if not r or r[0] is NIL: break
            parts.append(check_string(r[0],'load',1))
        text=''.join(parts)
    else:
        raise LuaError("bad argument #1 to 'load' (function or string expected, got %s)" % lua_type(chunk))
    try:
        block=Parser(text, chunkname).parse()
    except LuaError as e:
        return [NIL, "%s:%s: %s" % (e.source or chunkname, e.line or 1, e.message)]
    return [UserFunction([], True, block, GLOBAL_ENV, chunkname, 1)]
@bf('loadfile')
def b_loadfile(args):
    filename=arg(args,0,NIL)
    try:
        if filename is NIL: text=sys.stdin.read(); src='stdin'
        else:
            src=check_string(filename,'loadfile',1)
            with open(src,'r',encoding='utf-8') as f: text=f.read()
        block=Parser(text, '@'+src if filename is not NIL else 'stdin').parse()
        return [UserFunction([], True, block, GLOBAL_ENV, '@'+src if filename is not NIL else 'stdin', 1)]
    except OSError as e:
        return [NIL, str(e)]
    except LuaError as e:
        return [NIL, "%s:%s: %s" % (e.source, e.line, e.message)]
@bf('dofile')
def b_dofile(args):
    f=first(b_loadfile(args))
    if f is NIL: raise LuaError(arg(b_loadfile(args),1,'cannot open file'))
    return call_lua(f, [])

