# string patterns (small translator)
LUA_CLASS = {
    'a':'A-Za-z','d':'0-9','s':'\t\n\r\f\v ','w':'A-Za-z0-9_','l':'a-z','u':'A-Z','x':'0-9A-Fa-f','p':r'!"\#\$%&\'\(\)\*\+,\-\./:;<=>\?@\[\\\]\^_`\{\|\}\~',
    'c':'\x00-\x1f\x7f','z':'\x00'
}
def lua_pattern_to_regex(pat):
    i=0; out=''; anchored_start=False
    if pat.startswith('^'):
        out+='^'; i=1; anchored_start=True
    while i < len(pat):
        c=pat[i]
        if c=='$' and i==len(pat)-1:
            out+='$'; i+=1; continue
        if c=='%':
            i+=1
            if i>=len(pat): out+=re.escape('%'); break
            d=pat[i]
            if d in LUA_CLASS:
                out+='['+LUA_CLASS[d]+']'
            elif d.lower() in LUA_CLASS and d.isupper():
                out+='[^'+LUA_CLASS[d.lower()]+']'
            else:
                out+=re.escape(d)
        elif c=='.': out+='.'
        elif c in '*+-?': out+=re.escape(c)
        elif c=='-': out+='*?'
        elif c in '()': out+=c
        elif c=='[':
            j=i+1; neg=False
            if j<len(pat) and pat[j]=='^': neg=True; j+=1
            content=''
            while j<len(pat) and pat[j]!=']':
                if pat[j]=='%' and j+1<len(pat):
                    j+=1; d=pat[j]
                    if d in LUA_CLASS: content+=LUA_CLASS[d]
                    elif d.lower() in LUA_CLASS and d.isupper(): content+='^'+LUA_CLASS[d.lower()]
                    else: content+=re.escape(d)
                else:
                    content+=pat[j]
                j+=1
            out+='['+('^' if neg else '')+content+']'; i=j
        elif c in '^$*+?.{}\\|': out+=re.escape(c)
        else: out+=re.escape(c)
        # translate following repetition modifiers
        if i+1 < len(pat) and pat[i+1] in '*+?-':
            q=pat[i+1]
            if q=='-': out+='*?'
            else: out+=q
            i+=1
        i+=1
    return out

def str_find_impl(s, pattern, init=1, plain=False):
    if init<0: init=len(s)+init+1
    if init<1: init=1
    start=init-1
    if plain:
        pos=s.find(pattern,start)
        if pos<0: return [NIL]
        return [pos+1,pos+len(pattern)]
    try: rx=re.compile(lua_pattern_to_regex(pattern), re.S)
    except Exception:
        rx=re.compile(re.escape(pattern), re.S)
    m=rx.search(s,start)
    if not m: return [NIL]
    caps=list(m.groups())
    return [m.start()+1,m.end()] + [c if c is not None else NIL for c in caps]
