    except Exception: rx=re.compile(re.escape(p), re.S)
    it=iter(rx.finditer(s))
    def nxt(a):
        try: m=next(it)
        except StopIteration: return [NIL]
        gs=list(m.groups())
        if gs: return [g if g is not None else NIL for g in gs]
        return [m.group(0)]
    return [BuiltinFunction('gmatch iterator', nxt)]
@bf('string.gsub')
def string_gsub(args):
    s=check_string(arg(args,0),'gsub',1); p=check_string(arg(args,1),'gsub',2); repl=arg(args,2); maxn=check_int_arg(arg(args,3,10**9),'gsub',4)
    rx=re.compile(lua_pattern_to_regex(p), re.S); count=0
    def subfn(m):
        nonlocal count
        if count>=maxn: return m.group(0)
        count+=1
        caps=list(m.groups()) or [m.group(0)]
        if isinstance(repl,str):
            def rr(mm):
                n=mm.group(1)
                if n=='0': return m.group(0)
                idx=int(n); return caps[idx-1] if 1<=idx<=len(caps) else ''
            return re.sub(r'%([0-9])', rr, repl).replace('%%','%')
        if isinstance(repl,LuaTable):
            v=repl.rawget(caps[0]); return m.group(0) if v is NIL else lua_tostring(v)
        if isinstance(repl,(BuiltinFunction,UserFunction)):
            v=first(call_lua(repl,caps)); return m.group(0) if v is NIL or v is False else lua_tostring(v)
        return lua_tostring(repl)
    return [rx.sub(subfn,s), count]
@bf('string.format')
def string_format(args):
    fmt=check_string(arg(args,0),'format',1)
    pyargs=[]
    for a in args[1:]:
        if a is NIL: pyargs.append('nil')
        elif isinstance(a,bool): pyargs.append('true' if a else 'false')
        else: pyargs.append(a)
    try:
        return [fmt % tuple(pyargs)]
    except Exception:
        # simple Lua %q
        if '%q' in fmt:
            vals=[]
            for a in args[1:]: vals.append('"'+str(lua_tostring(a)).replace('\\','\\\\').replace('"','\\"').replace('\n','\\n')+'"')
            out=fmt.replace('%q','%s') % tuple(vals)
            return [out]
        raise LuaError("bad argument #1 to 'format' (invalid format)")

