#!/usr/bin/env python3
"""A small, original Lua-like interpreter targeting the observable Lua CLI behavior."""
import sys, os, math, re, time, datetime, random, subprocess, traceback as pytraceback
from dataclasses import dataclass
from functools import cmp_to_key

VERSION_LINE = "Lua 5.5.1  Copyright (C) 1994-2026 Lua.org, PUC-Rio"
LUA_VERSION = "Lua 5.5"
PROGNAME = None

# ------------------------------ values ------------------------------
class LuaNil:
    __slots__ = ()
    def __repr__(self): return "nil"
NIL = LuaNil()

class LuaError(Exception):
    def __init__(self, message, source=None, line=None):
        super().__init__(message)
        self.message = str(message)
        self.source = source
        self.line = line

class ReturnSignal(Exception):
    def __init__(self, values): self.values = values
class BreakSignal(Exception): pass
class GotoSignal(Exception):
    def __init__(self, label): self.label = label
class YieldSignal(Exception):
    def __init__(self, values): self.values = values


def is_nil(v): return v is NIL

def lua_truth(v): return not (v is NIL or v is False)

def is_lua_int(v): return isinstance(v, int) and not isinstance(v, bool)
def is_lua_float(v): return isinstance(v, float)
def is_lua_number(v): return is_lua_int(v) or is_lua_float(v)

def normalize_key(k):
    if k is NIL:
        raise LuaError("table index is nil")
    if isinstance(k, float) and math.isnan(k):
        raise LuaError("table index is NaN")
    if isinstance(k, bool):
        return ('bool', k)
    if is_lua_int(k):
        return ('num', k)
    if is_lua_float(k):
        if k == 0: k = 0.0
        if k.is_integer():
            return ('num', int(k))
        return ('float', k)
    if isinstance(k, str):
        return ('str', k)
    return ('obj', id(k))

class LuaTable:
    __slots__ = ('map', 'metatable')
    def __init__(self, init=None):
        self.map = {}
        self.metatable = NIL
        if init:
            for k, v in init:
                self.rawset(k, v)
    def rawget(self, key):
        ent = self.map.get(normalize_key(key))
        return NIL if ent is None else ent[1]
    def rawset(self, key, value):
        nk = normalize_key(key)
        if value is NIL:
            self.map.pop(nk, None)
        else:
            self.map[nk] = (key, value)
    def length(self):
        n = 0
        while True:
            if self.rawget(n+1) is NIL:
                return n
            n += 1
    def keys_values(self):
        for k, v in list(self.map.values()):
            if v is not NIL:
                yield k, v

class BuiltinFunction:
    __slots__ = ('name', 'func')
    def __init__(self, name, func):
        self.name = name; self.func = func

class UserFunction:
    __slots__ = ('params', 'vararg', 'body', 'env', 'source', 'line', 'name')
    def __init__(self, params, vararg, body, env, source=None, line=1, name=None):
        self.params=params; self.vararg=vararg; self.body=body; self.env=env
        self.source=source; self.line=line; self.name=name

class LuaFile:
    __slots__ = ('f', 'closed', 'stdname')
    def __init__(self, f, stdname=None):
        self.f=f; self.closed=False; self.stdname=stdname

class LuaCoroutine:
    __slots__ = ('func', 'status', 'dead_result')
    def __init__(self, func):
        self.func=func; self.status='suspended'; self.dead_result=None


def lua_type(v):
    if v is NIL: return 'nil'
    if isinstance(v, bool): return 'boolean'
    if is_lua_number(v): return 'number'
    if isinstance(v, str): return 'string'
    if isinstance(v, LuaTable): return 'table'
    if isinstance(v, (BuiltinFunction, UserFunction)): return 'function'
    if isinstance(v, LuaCoroutine): return 'thread'
    if isinstance(v, LuaFile): return 'userdata'
    return 'userdata'


def format_float(x):
    if math.isnan(x):
        return "-nan"
    if math.isinf(x):
        return "inf" if x > 0 else "-inf"
    s = format(x, '.17g')
    if 'e' not in s and 'E' not in s and '.' not in s:
        s += '.0'
    return s


def lua_tostring(v):
    mt = get_metatable(v)
    if isinstance(mt, LuaTable):
        mm = mt.rawget('__tostring')
        if mm is not NIL:
            try:
                res = call_lua(mm, [v])
                if res: return lua_to_string_arg(res[0])
            except LuaError:
                pass
    if v is NIL: return 'nil'
    if v is True: return 'true'
    if v is False: return 'false'
    if is_lua_int(v): return str(v)
    if is_lua_float(v): return format_float(v)
    if isinstance(v, str): return v
    if isinstance(v, LuaTable): return 'table: 0x%x' % (id(v) & 0xffffffffffff)
    if isinstance(v, (BuiltinFunction, UserFunction)): return 'function: 0x%x' % (id(v) & 0xffffffffffff)
    if isinstance(v, LuaCoroutine): return 'thread: 0x%x' % (id(v) & 0xffffffffffff)
    if isinstance(v, LuaFile): return 'file (%s)' % ('closed' if v.closed else hex(id(v)))
    return str(v)

def lua_to_string_arg(v):
    if isinstance(v, str): return v
    return lua_tostring(v)

# ------------------------------ tables/metatables ------------------------------
STRING_TABLE = None
STRING_MT = None

def get_metatable(v):
    if isinstance(v, LuaTable): return v.metatable
    if isinstance(v, str): return STRING_MT if STRING_MT is not None else NIL
    return NIL

def raw_get(obj, key):
    if isinstance(obj, LuaTable):
        return obj.rawget(key)
    raise LuaError("bad argument #1 to 'rawget' (table expected, got %s)" % lua_type(obj))

def raw_set(obj, key, value):
    if isinstance(obj, LuaTable):
        obj.rawset(key, value); return obj
    raise LuaError("bad argument #1 to 'rawset' (table expected, got %s)" % lua_type(obj))

def get_table(obj, key):
    if isinstance(obj, LuaTable):
        v = obj.rawget(key)
        if v is not NIL:
            return v
        mt = obj.metatable
        if isinstance(mt, LuaTable):
            idx = mt.rawget('__index')
            if idx is not NIL:
                if isinstance(idx, LuaTable): return get_table(idx, key)
                return first(call_lua(idx, [obj, key]))
        return NIL
    if isinstance(obj, str):
        mt = get_metatable(obj)
        if isinstance(mt, LuaTable):
            idx = mt.rawget('__index')
            if isinstance(idx, LuaTable):
                v = idx.rawget(key)
                if v is not NIL: return v
            elif idx is not NIL:
                return first(call_lua(idx, [obj, key]))
    raise LuaError("attempt to index a %s value" % lua_type(obj))

def set_table(obj, key, value):
    if isinstance(obj, LuaTable):
        old = obj.rawget(key)
        if old is NIL:
            mt = obj.metatable
            if isinstance(mt, LuaTable):
                ni = mt.rawget('__newindex')
                if ni is not NIL:
                    if isinstance(ni, LuaTable):
                        set_table(ni, key, value); return
                    call_lua(ni, [obj, key, value]); return
        obj.rawset(key, value); return
    raise LuaError("attempt to index a %s value" % lua_type(obj))

# ------------------------------ environment ------------------------------
class Env:
    __slots__ = ('parent', 'locals', 'globals', 'varargs')
    def __init__(self, parent=None, globals=None, varargs=None):
        self.parent = parent
        self.locals = {}
        self.globals = globals if globals is not None else (parent.globals if parent else LuaTable())
        self.varargs = [] if varargs is None else varargs
    def define(self, name, val=NIL):
        self.locals[name] = val
    def find_env(self, name):
        e = self
        while e is not None:
            if name in e.locals:
                return e
            e = e.parent
        return None
    def get(self, name):
        e = self.find_env(name)
        if e is not None:
            return e.locals[name]
        return self.globals.rawget(name)
    def set(self, name, val):
        e = self.find_env(name)
        if e is not None:
            e.locals[name] = val
        else:
            self.globals.rawset(name, val)

# ------------------------------ lexer ------------------------------
KEYWORDS = set('and break do else elseif end false for function goto if in local nil not or repeat return then true until while'.split())

@dataclass
class Token:
    kind: str
    value: object
    line: int
    col: int
    raw: str = ''

class Lexer:
    def __init__(self, text, source='(string)'):
        if text.startswith('#'):
            nl = text.find('\n')
            if nl >= 0:
                text = '\n' + text[nl+1:]
            else:
                text = ''
        self.text=text; self.source=source; self.i=0; self.line=1; self.col=1; self.n=len(text)
    def peek(self, off=0):
        j=self.i+off
        return '' if j>=self.n else self.text[j]
    def advance(self, n=1):
        s=''
        for _ in range(n):
            if self.i>=self.n: break
            c=self.text[self.i]; self.i+=1; s+=c
            if c=='\n': self.line+=1; self.col=1
            else: self.col+=1
        return s
    def error(self, msg):
        raise LuaError(msg, self.source, self.line)
    def skip_space_comments(self):
        while True:
            c=self.peek()
            if c and c.isspace():
                self.advance(); continue
            if c=='-' and self.peek(1)=='-':
                self.advance(2)
                if self.peek()=='[':
                    eq = self.long_bracket_level(self.i)
                    if eq is not None:
                        self.read_long(eq); continue
                while self.peek() and self.peek()!='\n': self.advance()
                continue
            break
    def long_bracket_level(self, pos):
        if pos>=self.n or self.text[pos] != '[': return None
        j=pos+1; eq=0
        while j<self.n and self.text[j]=='=':
            eq+=1; j+=1
        if j<self.n and self.text[j]=='[': return eq
        return None
    def read_long(self, eq):
        # current char is '['
        self.advance(1+eq+1)
        if self.peek()=='\n': self.advance()
        out=[]
        while True:
            if self.i>=self.n: self.error('unfinished long string')
            if self.peek()==']':
                j=self.i+1; cnt=0
                while j<self.n and self.text[j]=='=':
                    cnt+=1; j+=1
                if cnt==eq and j<self.n and self.text[j]==']':
                    self.advance(1+eq+1); break
            out.append(self.advance())
        return ''.join(out)
    def read_string(self, quote):
        start_line=self.line
        self.advance()
        out=[]
        while True:
            c=self.peek()
            if c=='': raise LuaError('unfinished string near <eof>', self.source, start_line)
            if c=='\n' or c=='\r': raise LuaError('unfinished string near <eol>', self.source, start_line)
            if c==quote:
                self.advance(); break
            if c!='\\':
                out.append(self.advance()); continue
            self.advance()
            e=self.peek()
            if e=='': raise LuaError('unfinished string near <eof>', self.source, start_line)
            maps={'a':'\a','b':'\b','f':'\f','n':'\n','r':'\r','t':'\t','v':'\v','\\':'\\','"':'"',"'":"'"}
            if e in maps:
                out.append(maps[e]); self.advance()
            elif e=='\n': self.advance(); out.append('\n')
            elif e=='\r':
                self.advance();
                if self.peek()=='\n': self.advance()
                out.append('\n')
            elif e=='z':
                self.advance()
                while self.peek() and self.peek().isspace(): self.advance()
            elif e=='x':
                self.advance(); hx=self.advance(2)
                try: out.append(chr(int(hx,16)))
                except Exception: self.error('hexadecimal digit expected')
            elif e=='u' and self.peek(1)=='{':
                self.advance(2); hx=''
                while self.peek() and self.peek()!='}': hx+=self.advance()
                if self.peek()=='}': self.advance()
                try: out.append(chr(int(hx,16)))
                except Exception: self.error('UTF-8 value too large')
            elif e.isdigit():
                digs=''
                for _ in range(3):
                    if self.peek().isdigit(): digs += self.advance()
                    else: break
                val=int(digs,10)
                if val>255: self.error('decimal escape too large')
                out.append(chr(val))
            else:
                out.append(self.advance())
        return ''.join(out)
    def read_number(self):
        start=self.i; line=self.line; col=self.col
        if self.peek()=='.':
            self.advance()
            while self.peek().isdigit(): self.advance()
            if self.peek() in 'eE':
                self.advance()
                if self.peek() in '+-': self.advance()
                while self.peek().isdigit(): self.advance()
        elif self.peek()=='0' and self.peek(1) in 'xX':
            self.advance(2)
            while self.peek().isdigit() or self.peek().lower() in 'abcdef': self.advance()
            if self.peek()=='.':
                self.advance()
                while self.peek().isdigit() or self.peek().lower() in 'abcdef': self.advance()
            if self.peek() in 'pP':
                self.advance()
                if self.peek() in '+-': self.advance()
                while self.peek().isdigit(): self.advance()
        else:
            while self.peek().isdigit(): self.advance()
            if self.peek()=='.' and self.peek(1)!='.':
                self.advance()
                while self.peek().isdigit(): self.advance()
            if self.peek() in 'eE':
                self.advance()
                if self.peek() in '+-': self.advance()
                while self.peek().isdigit(): self.advance()
        raw=self.text[start:self.i]
        try:
            if raw.lower().startswith('0x'):
                if any(ch in raw for ch in '.pP'):
                    val=float.fromhex(raw)
                else:
                    val=int(raw,16)
            else:
                if any(ch in raw for ch in '.eE'):
                    val=float(raw)
                else:
                    val=int(raw,10)
        except Exception:
            raise LuaError('malformed number near %r' % raw, self.source, line)
        return Token('NUMBER', val, line, col, raw)
    def next_token(self):
        self.skip_space_comments()
        line=self.line; col=self.col; c=self.peek()
        if c=='': return Token('EOF', None, line, col, '')
        if c.isalpha() or c=='_':
            s=''
            while self.peek().isalnum() or self.peek()=='_': s += self.advance()
            if s in KEYWORDS: return Token(s, s, line, col, s)
            return Token('NAME', s, line, col, s)
        if c.isdigit() or (c=='.' and self.peek(1).isdigit()):
            return self.read_number()
        if c in ('"', "'"):
            rawq=c; val=self.read_string(c); return Token('STRING', val, line, col, rawq)
        if c=='[':
            eq=self.long_bracket_level(self.i)
            if eq is not None:
                val=self.read_long(eq); return Token('STRING', val, line, col, '')
        three=self.text[self.i:self.i+3]
        if three=='...': self.advance(3); return Token('...', '...', line, col, '...')
        two=self.text[self.i:self.i+2]
        if two in ('==','~=','<=','>=','//','..','<<','>>','::'):
            self.advance(2); return Token(two, two, line, col, two)
        self.advance(); return Token(c, c, line, col, c)

# ------------------------------ AST ------------------------------
@dataclass
class Block: stmts: list
@dataclass
class Number: value: object; line:int
@dataclass
class String: value: str; line:int
@dataclass
class Bool: value: bool; line:int
@dataclass
class NilExpr: line:int
@dataclass
class VarArg: line:int
@dataclass
class NameExpr: name:str; line:int
@dataclass
class IndexExpr: obj:object; key:object; line:int
@dataclass
class CallExpr: func:object; args:list; method:str=None; line:int=1
@dataclass
class FunctionExpr: params:list; vararg:bool; body:Block; line:int
@dataclass
class TableExpr: fields:list; line:int
@dataclass
class UnaryExpr: op:str; expr:object; line:int
@dataclass
class BinaryExpr: op:str; left:object; right:object; line:int
@dataclass
class ParenExpr: expr:object; line:int

@dataclass
class AssignStmt: vars:list; exprs:list; line:int
@dataclass
class LocalAssignStmt: names:list; exprs:list; line:int
@dataclass
class CallStmt: call:CallExpr; line:int
@dataclass
class ReturnStmt: exprs:list; line:int
@dataclass
class BreakStmt: line:int
@dataclass
class GotoStmt: label:str; line:int
@dataclass
class LabelStmt: label:str; line:int
@dataclass
class DoStmt: block:Block; line:int
@dataclass
class WhileStmt: cond:object; block:Block; line:int
@dataclass
class RepeatStmt: block:Block; cond:object; line:int
@dataclass
class IfStmt: clauses:list; elseblock:Block; line:int
@dataclass
class NumForStmt: name:str; start:object; limit:object; step:object; block:Block; line:int
@dataclass
class GenForStmt: names:list; exprs:list; block:Block; line:int
@dataclass
class FunctionStmt: target:object; func:FunctionExpr; line:int
@dataclass
class LocalFunctionStmt: name:str; func:FunctionExpr; line:int

class Parser:
    BINPREC = {
        'or':1, 'and':2,
        '<':3, '>':3, '<=':3, '>=':3, '~=':3, '==':3,
        '|':4, '~':5, '&':6, '<<':7, '>>':7,
        '..':8,
        '+':9, '-':9,
        '*':10, '/':10, '//':10, '%':10,
        '^':12,
    }
    RIGHT = {'..','^'}
    UNARY = {'not','#','-','~'}
    def __init__(self, text, source='(string)'):
        self.lexer=Lexer(text, source); self.source=source; self.tok=self.lexer.next_token()
    def error(self, msg=None):
        if msg is None:
            msg = "unexpected symbol near '%s'" % (self.tok.raw or self.tok.kind)
        raise LuaError(msg, self.source, self.tok.line)
    def advance(self):
        old=self.tok; self.tok=self.lexer.next_token(); return old
    def check(self, kind): return self.tok.kind==kind
    def accept(self, kind):
        if self.check(kind): return self.advance()
        return None
    def expect(self, kind):
        if not self.check(kind): self.error("'%s' expected near '%s'" % (kind, self.tok.raw or self.tok.kind))
        return self.advance()
    def parse(self):
        b=self.parse_block(set(['EOF']))
        self.expect('EOF')
        return b
    def parse_block(self, terminators):
        stmts=[]
        while self.tok.kind not in terminators and self.tok.kind!='EOF':
            if self.check('return'):
                stmts.append(self.parse_return())
                self.accept(';')
                # Lua requires return as last; we stop until terminator for leniency
                while self.accept(';'): pass
                if self.tok.kind not in terminators and self.tok.kind!='EOF':
                    # leave subsequent parse to produce closer behavior? accept anyway
                    pass
            else:
                st=self.parse_stat()
                if st is not None: stmts.append(st)
                while self.accept(';'): pass
        return Block(stmts)
    def parse_return(self):
        t=self.expect('return')
        exprs=[]
        if self.tok.kind not in ('EOF','end','else','elseif','until',';'):
            exprs=self.parse_explist()
        return ReturnStmt(exprs, t.line)
    def parse_stat(self):
        if self.accept(';'): return None
        if self.check('::'):
            line=self.advance().line; name=self.expect('NAME').value; self.expect('::'); return LabelStmt(name,line)
        if self.check('break'):
            return BreakStmt(self.advance().line)
        if self.check('goto'):
            line=self.advance().line; name=self.expect('NAME').value; return GotoStmt(name,line)
        if self.check('do'):
            line=self.advance().line; b=self.parse_block({'end'}); self.expect('end'); return DoStmt(b,line)
        if self.check('while'):
            line=self.advance().line; cond=self.parse_exp(); self.expect('do'); b=self.parse_block({'end'}); self.expect('end'); return WhileStmt(cond,b,line)
        if self.check('repeat'):
            line=self.advance().line; b=self.parse_block({'until'}); self.expect('until'); cond=self.parse_exp(); return RepeatStmt(b,cond,line)
        if self.check('if'):
            return self.parse_if()
        if self.check('for'):
            return self.parse_for()
        if self.check('function'):
            return self.parse_function_stmt()
        if self.check('local'):
            return self.parse_local()
        # assignment or function call
        line=self.tok.line
        first=self.parse_prefixexp()
        if isinstance(first, CallExpr) and not self.check(',') and not self.check('='):
            return CallStmt(first,line)
        vars=[first]
        while self.accept(','):
            vars.append(self.parse_prefixexp())
        self.expect('=')
        exprs=self.parse_explist()
        return AssignStmt(vars, exprs, line)
    def parse_if(self):
        line=self.expect('if').line
        clauses=[]
        cond=self.parse_exp(); self.expect('then'); b=self.parse_block({'elseif','else','end'}); clauses.append((cond,b))
        while self.accept('elseif'):
            cond=self.parse_exp(); self.expect('then'); b=self.parse_block({'elseif','else','end'}); clauses.append((cond,b))
        elseblock=None
        if self.accept('else'):
            elseblock=self.parse_block({'end'})
        self.expect('end')
        return IfStmt(clauses, elseblock, line)
    def parse_for(self):
        line=self.expect('for').line
        name=self.expect('NAME').value
        if self.accept('='):
            start=self.parse_exp(); self.expect(','); limit=self.parse_exp();
            if self.accept(','): step=self.parse_exp()
            else: step=Number(1,line)
            self.expect('do'); b=self.parse_block({'end'}); self.expect('end')
            return NumForStmt(name,start,limit,step,b,line)
        names=[name]
        while self.accept(','): names.append(self.expect('NAME').value)
        self.expect('in'); exprs=self.parse_explist(); self.expect('do'); b=self.parse_block({'end'}); self.expect('end')
        return GenForStmt(names,exprs,b,line)
    def parse_function_stmt(self):
        line=self.expect('function').line
        target, method = self.parse_funcname()
        func=self.parse_funcbody(line)
        if method:
            func.params = ['self'] + func.params
        return FunctionStmt(target, func, line)
    def parse_funcname(self):
        line=self.tok.line
        expr=NameExpr(self.expect('NAME').value,line)
        while self.accept('.'):
            key=String(self.expect('NAME').value,self.tok.line)
            expr=IndexExpr(expr,key,line)
        method=False
        if self.accept(':'):
            key=String(self.expect('NAME').value,self.tok.line)
            expr=IndexExpr(expr,key,line); method=True
        return expr, method
    def parse_local(self):
        line=self.expect('local').line
        if self.accept('function'):
            name=self.expect('NAME').value; func=self.parse_funcbody(line); return LocalFunctionStmt(name,func,line)
        names=[]
        names.append(self.expect('NAME').value)
        # ignore attributes <const>/<close>
        if self.accept('<'):
            if self.check('NAME'): self.advance()
            self.expect('>')
        while self.accept(','):
            names.append(self.expect('NAME').value)
            if self.accept('<'):
                if self.check('NAME'): self.advance()
                self.expect('>')
        exprs=[]
        if self.accept('='): exprs=self.parse_explist()
        return LocalAssignStmt(names,exprs,line)
    def parse_funcbody(self, line=None):
        if line is None: line=self.tok.line
        self.expect('(')
        params=[]; vararg=False
        if not self.check(')'):
            if self.accept('...'):
                vararg=True
            else:
                params.append(self.expect('NAME').value)
                while self.accept(','):
                    if self.accept('...'):
                        vararg=True; break
                    params.append(self.expect('NAME').value)
        self.expect(')')
        b=self.parse_block({'end'}); self.expect('end')
        return FunctionExpr(params,vararg,b,line)
    def parse_explist(self):
        exprs=[self.parse_exp()]
        while self.accept(','):
            exprs.append(self.parse_exp())
        return exprs
    def parse_exp(self):
        return self.parse_subexpr(0)
    def parse_subexpr(self, limit):
        line=self.tok.line
        if self.tok.kind in self.UNARY:
            op=self.advance().kind
            left=UnaryExpr(op, self.parse_subexpr(11), line)
        else:
            left=self.parse_simpleexp()
        while True:
            op=self.tok.kind
            if op not in self.BINPREC: break
            prec=self.BINPREC[op]
            if prec <= limit: break
            self.advance()
            nextlimit = prec-1 if op in self.RIGHT else prec
            right=self.parse_subexpr(nextlimit)
            left=BinaryExpr(op,left,right,line)
        return left
    def parse_simpleexp(self):
        t=self.tok; k=t.kind
        if k=='NUMBER': self.advance(); return Number(t.value,t.line)
        if k=='STRING': self.advance(); return String(t.value,t.line)
        if k=='nil': self.advance(); return NilExpr(t.line)
        if k=='true': self.advance(); return Bool(True,t.line)
        if k=='false': self.advance(); return Bool(False,t.line)
        if k=='...': self.advance(); return VarArg(t.line)
        if k=='function':
            line=self.advance().line; return self.parse_funcbody(line)
        if k=='{': return self.parse_tableconstructor()
        return self.parse_prefixexp()
    def parse_tableconstructor(self):
        line=self.expect('{').line
        fields=[]
        if not self.check('}'):
            while True:
                if self.check('['):
                    self.advance(); key=self.parse_exp(); self.expect(']'); self.expect('='); val=self.parse_exp(); fields.append(('key',key,val))
                elif self.check('NAME') and self.lexer.peek_nonexistent if False else False:
                    pass
                else:
                    # name = exp special needs lookahead; use current token and temporary advance
                    if self.check('NAME'):
                        save_tok=self.tok; save_i=self.lexer.i; save_line=self.lexer.line; save_col=self.lexer.col
                        name=self.advance().value
                        if self.accept('='):
                            val=self.parse_exp(); fields.append(('key',String(name,save_tok.line),val))
                        else:
                            self.tok=save_tok; self.lexer.i=save_i; self.lexer.line=save_line; self.lexer.col=save_col
                            fields.append(('value', self.parse_exp()))
                    else:
                        fields.append(('value', self.parse_exp()))
                if self.accept(',') or self.accept(';'):
                    if self.check('}'): break
                    continue
                break
        self.expect('}')
        return TableExpr(fields,line)
    def parse_prefixexp(self):
        line=self.tok.line
        if self.check('NAME'):
            expr=NameExpr(self.advance().value,line)
        elif self.accept('('):
            e=self.parse_exp(); self.expect(')'); expr=ParenExpr(e,line)
        else:
            self.error()
        while True:
            if self.accept('['):
                key=self.parse_exp(); self.expect(']'); expr=IndexExpr(expr,key,line)
            elif self.accept('.'):
                key=String(self.expect('NAME').value,line); expr=IndexExpr(expr,key,line)
            elif self.accept(':'):
                m=self.expect('NAME').value; args=self.parse_args(); expr=CallExpr(expr,args,m,line)
            elif self.tok.kind in ('(', '{', 'STRING'):
                args=self.parse_args(); expr=CallExpr(expr,args,None,line)
            else:
                break
        return expr
    def parse_args(self):
        if self.accept('('):
            args=[]
            if not self.check(')'):
                args=self.parse_explist()
            self.expect(')'); return args
        if self.check('{'):
            return [self.parse_tableconstructor()]
        if self.check('STRING'):
            t=self.advance(); return [String(t.value,t.line)]
        self.error('function arguments expected')

# ------------------------------ evaluation helpers ------------------------------
def first(vals):
    if vals is None: return NIL
    return vals[0] if len(vals)>0 else NIL

def adjust(vals, n):
    vals=list(vals)
    if len(vals)<n: vals += [NIL]*(n-len(vals))
    return vals[:n]

def eval_expr_list(exprs, env, expected=None):
    vals=[]
    for i,e in enumerate(exprs):
        if i == len(exprs)-1:
            vals.extend(eval_multi(e, env))
        else:
            vals.append(eval_single(e, env))
    if expected is not None:
        vals=adjust(vals, expected)
    return vals

def eval_single(expr, env):
    return first(eval_multi(expr, env))

def eval_multi(expr, env):
    if isinstance(expr, CallExpr): return eval_call(expr, env)
    if isinstance(expr, VarArg): return list(env.varargs)
    if isinstance(expr, ParenExpr): return [eval_single(expr.expr, env)]
    return [eval_expr(expr, env)]


def to_number(v):
    if is_lua_number(v): return v
    if isinstance(v, str):
        n = parse_lua_number(v.strip())
        if n is not None: return n
    return None

def parse_lua_number(s):
    if s == '': return None
    try:
        if s.lower().startswith(('0x','+0x','-0x')):
            if any(ch in s for ch in '.pP'):
                return float.fromhex(s)
            return int(s,16)
        if re.match(r'^[+-]?\d+$', s): return int(s,10)
        return float(s)
    except Exception:
        return None

def require_number(v, op='perform arithmetic on'):
    n=to_number(v)
    if n is None:
        raise LuaError("attempt to %s a %s value" % (op, lua_type(v)))
    return n

def require_int(v):
    if is_lua_int(v): return v
    raise LuaError("number has no integer representation" if is_lua_number(v) else "attempt to perform bitwise operation on a %s value" % lua_type(v))

def wrap64(n):
    n &= (1<<64)-1
    if n >= (1<<63): n -= (1<<64)
    return n

def unsigned64(n): return n & ((1<<64)-1)

def lua_arith(op,a,b=None):
    if op=='unm':
        x=require_number(a)
        return -x
    if op=='+':
        x=require_number(a); y=require_number(b)
        return x+y if (is_lua_float(x) or is_lua_float(y)) else wrap64(x+y)
    if op=='-':
        x=require_number(a); y=require_number(b)
        return x-y if (is_lua_float(x) or is_lua_float(y)) else wrap64(x-y)
    if op=='*':
        x=require_number(a); y=require_number(b)
        return x*y if (is_lua_float(x) or is_lua_float(y)) else wrap64(x*y)
    if op=='/':
        x=require_number(a); y=require_number(b); return float(x)/float(y)
    if op=='//':
        x=require_number(a); y=require_number(b); r=math.floor(x/y)
        return float(r) if (is_lua_float(x) or is_lua_float(y)) else int(r)
    if op=='%':
        x=require_number(a); y=require_number(b); r=x - math.floor(x/y)*y
        return float(r) if (is_lua_float(x) or is_lua_float(y)) else int(r)
    if op=='^':
        x=require_number(a); y=require_number(b); return float(x) ** float(y)
    raise LuaError('unknown arithmetic op')

def lua_bit(op,a,b=None):
    if op=='bnot': return wrap64(~require_int(a))
    x=require_int(a); y=require_int(b)
    if op=='&': return wrap64(x & y)
    if op=='|': return wrap64(x | y)
    if op=='~': return wrap64(x ^ y)
    if op=='<<':
        if y < 0: return lua_bit('>>', x, -y)
        return wrap64(unsigned64(x) << min(y, 64))
    if op=='>>':
        if y < 0: return lua_bit('<<', x, -y)
        if y >= 64: return 0
        return wrap64(unsigned64(x) >> y)
    raise LuaError('unknown bit op')

def lua_eq(a,b):
    if a is NIL and b is NIL: return True
    if is_lua_number(a) and is_lua_number(b): return float(a)==float(b)
    if type(a) is not type(b): return False
    if isinstance(a, (LuaTable, UserFunction, BuiltinFunction, LuaCoroutine, LuaFile)):
        return a is b
    return a == b

def lua_compare(op,a,b):
    if is_lua_number(a) and is_lua_number(b):
        x=float(a); y=float(b)
    elif isinstance(a,str) and isinstance(b,str):
        x=a; y=b
    else:
        raise LuaError("attempt to compare %s with %s" % (lua_type(a), lua_type(b)))
    if op=='<': return x<y
    if op=='>': return x>y
    if op=='<=': return x<=y
    if op=='>=': return x>=y
    return False

def lua_concat(a,b):
    if not (is_lua_number(a) or isinstance(a,str)) or not (is_lua_number(b) or isinstance(b,str)):
        raise LuaError("attempt to concatenate a %s value" % (lua_type(a) if not (is_lua_number(a) or isinstance(a,str)) else lua_type(b)))
    return lua_tostring(a) + lua_tostring(b)

def lua_len(v):
    mt=get_metatable(v)
    if isinstance(mt, LuaTable):
        mm=mt.rawget('__len')
        if mm is not NIL: return first(call_lua(mm,[v]))
    if isinstance(v,str): return len(v.encode('utf-8'))
    if isinstance(v,LuaTable): return v.length()
    raise LuaError("attempt to get length of a %s value" % lua_type(v))


def eval_expr(expr, env):
    if isinstance(expr, Number): return expr.value
    if isinstance(expr, String): return expr.value
    if isinstance(expr, Bool): return expr.value
    if isinstance(expr, NilExpr): return NIL
    if isinstance(expr, NameExpr): return env.get(expr.name)
    if isinstance(expr, IndexExpr): return get_table(eval_single(expr.obj, env), eval_single(expr.key, env))
    if isinstance(expr, FunctionExpr): return UserFunction(expr.params, expr.vararg, expr.body, env, CURRENT_SOURCE, expr.line)
    if isinstance(expr, TableExpr):
        t=LuaTable(); arr=1
        for idx,field in enumerate(expr.fields):
            if field[0]=='key':
                k=eval_single(field[1],env); v=eval_single(field[2],env); set_table(t,k,v)
            else:
                vals = eval_multi(field[1],env) if idx==len(expr.fields)-1 else [eval_single(field[1],env)]
                for v in vals:
                    set_table(t,arr,v); arr+=1
        return t
    if isinstance(expr, UnaryExpr):
        v=eval_single(expr.expr, env)
        if expr.op=='not': return not lua_truth(v)
        if expr.op=='-': return lua_arith('unm', v)
        if expr.op=='#': return lua_len(v)
        if expr.op=='~': return lua_bit('bnot', v)
    if isinstance(expr, BinaryExpr):
        op=expr.op
        if op=='and':
            a=eval_single(expr.left,env); return eval_single(expr.right,env) if lua_truth(a) else a
        if op=='or':
            a=eval_single(expr.left,env); return a if lua_truth(a) else eval_single(expr.right,env)
        if op=='..':
            # right associative AST already; simple concat
            return lua_concat(eval_single(expr.left,env), eval_single(expr.right,env))
        a=eval_single(expr.left,env); b=eval_single(expr.right,env)
        if op in ('+','-','*','/','//','%','^'): return lua_arith(op,a,b)
        if op in ('&','|','~','<<','>>'): return lua_bit(op,a,b)
        if op=='==': return lua_eq(a,b)
        if op=='~=': return not lua_eq(a,b)
        if op in ('<','>','<=','>='): return lua_compare(op,a,b)
    if isinstance(expr, ParenExpr): return eval_single(expr.expr, env)
    if isinstance(expr, CallExpr): return first(eval_call(expr,env))
    if isinstance(expr, VarArg): return first(env.varargs)
    raise LuaError('internal: unknown expression')


def eval_lvalue_target(var, env):
    if isinstance(var, NameExpr): return ('name', var.name)
    if isinstance(var, IndexExpr): return ('index', eval_single(var.obj, env), eval_single(var.key, env))
    raise LuaError('syntax error: assignment to non-variable')

def assign_target(target, value, env):
    if target[0]=='name': env.set(target[1], value)
    else: set_table(target[1], target[2], value)

CURRENT_SOURCE = '(string)'

def exec_block(block, env):
    labels={}
    for i,st in enumerate(block.stmts):
        if isinstance(st, LabelStmt): labels[st.label]=i
    pc=0
    while pc < len(block.stmts):
        st=block.stmts[pc]
        try:
            exec_stmt(st, env)
            pc += 1
        except GotoSignal as g:
            if g.label in labels:
                pc = labels[g.label]+1
            else:
                raise

def exec_stmt(st, env):
    if isinstance(st, AssignStmt):
        targets=[eval_lvalue_target(v,env) for v in st.vars]
        vals=eval_expr_list(st.exprs, env, len(targets))
        for t,v in zip(targets, vals): assign_target(t,v,env)
    elif isinstance(st, LocalAssignStmt):
        vals=eval_expr_list(st.exprs, env, len(st.names)) if st.exprs else [NIL]*len(st.names)
        for n,v in zip(st.names, vals): env.define(n,v)
    elif isinstance(st, CallStmt):
        eval_call(st.call, env)
    elif isinstance(st, ReturnStmt):
        raise ReturnSignal(eval_expr_list(st.exprs, env) if st.exprs else [])
    elif isinstance(st, BreakStmt):
        raise BreakSignal()
    elif isinstance(st, GotoStmt):
        raise GotoSignal(st.label)
    elif isinstance(st, LabelStmt):
        return
    elif isinstance(st, DoStmt):
        exec_block(st.block, Env(parent=env))
    elif isinstance(st, WhileStmt):
        while lua_truth(eval_single(st.cond,env)):
            try: exec_block(st.block, Env(parent=env))
            except BreakSignal: break
    elif isinstance(st, RepeatStmt):
        while True:
            try: exec_block(st.block, Env(parent=env))
            except BreakSignal: break
            if lua_truth(eval_single(st.cond, env)): break
    elif isinstance(st, IfStmt):
        for cond,b in st.clauses:
            if lua_truth(eval_single(cond,env)):
                exec_block(b, Env(parent=env)); return
        if st.elseblock is not None: exec_block(st.elseblock, Env(parent=env))
    elif isinstance(st, NumForStmt):
        start=require_number(eval_single(st.start,env)); limit=require_number(eval_single(st.limit,env)); step=require_number(eval_single(st.step,env))
        i=start
        def cont(i): return i <= limit if step >= 0 else i >= limit
        while cont(i):
            loop_env=Env(parent=env); loop_env.define(st.name, i)
            try: exec_block(st.block, loop_env)
            except BreakSignal: break
            i = i + step
    elif isinstance(st, GenForStmt):
        vals=eval_expr_list(st.exprs, env)
        gen=vals[0] if len(vals)>0 else NIL; state=vals[1] if len(vals)>1 else NIL; ctrl=vals[2] if len(vals)>2 else NIL
        while True:
            res=call_lua(gen, [state, ctrl])
            if len(res)==0 or res[0] is NIL: break
            ctrl=res[0]
            loop_env=Env(parent=env)
            for n,v in zip(st.names, adjust(res,len(st.names))): loop_env.define(n,v)
            try: exec_block(st.block, loop_env)
            except BreakSignal: break
    elif isinstance(st, FunctionStmt):
        f=UserFunction(st.func.params, st.func.vararg, st.func.body, env, CURRENT_SOURCE, st.func.line)
        target=eval_lvalue_target(st.target, env); assign_target(target, f, env)
    elif isinstance(st, LocalFunctionStmt):
        env.define(st.name, NIL)
        f=UserFunction(st.func.params, st.func.vararg, st.func.body, env, CURRENT_SOURCE, st.func.line, st.name)
        env.set(st.name, f)
    else:
        raise LuaError('internal: unknown statement')


def eval_call(call, env):
    func = eval_single(call.func, env)
    args=[]
    if call.method is not None:
        recv=func
        func=get_table(recv, call.method)
        args.append(recv)
    args.extend(eval_expr_list(call.args, env) if call.args else [])
    return call_lua(func, args)

def call_lua(func, args):
    if isinstance(func, BuiltinFunction):
        r=func.func(args)
        if r is None: return []
        if isinstance(r, list): return r
        return [r]
    if isinstance(func, UserFunction):
        newenv=Env(parent=func.env, varargs=[])
        for i,p in enumerate(func.params):
            newenv.define(p, args[i] if i<len(args) else NIL)
        if func.vararg:
            newenv.varargs = args[len(func.params):]
        try:
            exec_block(func.body, newenv)
            return []
        except ReturnSignal as r:
            return r.values
        except YieldSignal:
            raise
    if isinstance(func, LuaTable):
        mt=func.metatable
        if isinstance(mt,LuaTable):
            mm=mt.rawget('__call')
            if mm is not NIL: return call_lua(mm, [func]+args)
    raise LuaError("attempt to call a %s value" % lua_type(func))

