def parse_and_run(text, env, source='(string)', args=None):
    global CURRENT_SOURCE
    old=CURRENT_SOURCE; CURRENT_SOURCE=source
    try:
        block=Parser(text, source).parse()
        if args is not None: env.varargs=args
        exec_block(block, env)
        return []
    except ReturnSignal as r:
        return r.values
    finally:
        CURRENT_SOURCE=old

@bf('load')
def b_load(args):
    chunk=arg(args,0); chunkname=arg(args,1,'=(load)')
    if isinstance(chunk, str):
        text=chunk
    elif isinstance(chunk,(BuiltinFunction,UserFunction)):
        parts=[]
        while True:
            r=call_lua(chunk, [])
            if not r or r[0] is NIL: break
            parts.append(check_string(r[0],'load',1))
        text=''.join(parts)
    else:
        raise LuaError("bad argument #1 to 'load' (function or string expected, got %s)" % lua_type(chunk))
    try:
        block=Parser(text, chunkname).parse()
    except LuaError as e:
        return [NIL, "%s:%s: %s" % (e.source or chunkname, e.line or 1, e.message)]
    return [UserFunction([], True, block, GLOBAL_ENV, chunkname, 1)]
