        else:
            src=check_string(filename,'loadfile',1)
            with open(src,'r',encoding='utf-8') as f: text=f.read()
        block=Parser(text, '@'+src if filename is not NIL else 'stdin').parse()
        return [UserFunction([], True, block, GLOBAL_ENV, '@'+src if filename is not NIL else 'stdin', 1)]
    except OSError as e:
        return [NIL, str(e)]
    except LuaError as e:
        return [NIL, "%s:%s: %s" % (e.source, e.line, e.message)]
