PACKAGE_CONFIG = "/\n;\n?\n!\n-\n"

def expand_path_env(name, default):
    val=os.environ.get(name)
    if val is None:
        return default
    return val.replace(';;',';'+default+';')

def search_lua_file(modname):
    path=PACKAGE_TABLE.rawget('path') if PACKAGE_TABLE else DEFAULT_PATH
    sub=modname.replace('.', '/')
    tried=[]
    for template in str(path).split(';'):
        fn=template.replace('?', sub)
        if os.path.isfile(fn): return fn, ''
        tried.append("\n\tno file '%s'" % fn)
    return None, ''.join(tried)
@bf('require')
def b_require(args):
    name=check_string(arg(args,0),'require',1)
    loaded=LOADED_TABLE.rawget(name)
    if loaded is not NIL and loaded is not False: return [loaded]
    pre=PRELOAD_TABLE.rawget(name)
    if pre is not NIL:
        res=call_lua(pre,[name,':preload:'])
        mod=res[0] if res else True
        if mod is NIL: mod=True
        LOADED_TABLE.rawset(name, mod)
        return [mod, ':preload:']
    fn, err=search_lua_file(name)
    if fn:
        with open(fn,'r',encoding='utf-8') as f: text=f.read()
        fenv=Env(parent=GLOBAL_ENV)
        res=parse_and_run(text, fenv, '@'+fn, [name, fn])
        mod=res[0] if res else True
        if mod is NIL: mod=True
        LOADED_TABLE.rawset(name, mod)
        return [mod, fn]
    raise LuaError("module '%s' not found:%s" % (name, err))

