    f=check_file(arg(args,0),'read',1); formats=args[1:] or ['l']; out=[]
    for fmt in formats:
        if fmt is NIL: fmt='l'
        if is_lua_number(fmt):
            data=f.f.read(int(fmt)); out.append(data if data!='' else NIL)
        else:
            fmt=check_string(fmt,'read')
            if fmt in ('l','*l'):
                line=f.f.readline(); out.append((line[:-1] if line.endswith('\n') else line) if line!='' else NIL)
            elif fmt in ('L','*L'):
