            elif fmt in ('a','*a'):
                out.append(f.f.read())
            elif fmt in ('n','*n'):
                # simplistic token read
                token='';
                while True:
                    ch=f.f.read(1)
                    if ch=='' or ch.isspace():
                        if token: break
                        if ch=='': break
                        continue
                    token+=ch
                out.append(parse_lua_number(token) if token else NIL)
            else: raise LuaError("bad argument to 'read' (invalid format)")
    return out
