@bf('coroutine.resume')
def co_resume(args):
    co=arg(args,0)
    if not isinstance(co,LuaCoroutine): raise LuaError("bad argument #1 to 'resume' (thread expected)")
    if co.status=='dead': return [False, 'cannot resume dead coroutine']
    co.status='running'
    try:
        res=call_lua(co.func,args[1:]); co.status='dead'; return [True]+res
    except YieldSignal as y:
        co.status='suspended'; return [True]+y.values
    except LuaError as e:
        co.status='dead'; return [False,e.message]
