# ------------------------------ CLI ------------------------------
USAGE = """usage: {prog} [options] [script [args]]
Available options are:
  -e stat   execute string 'stat'
  -i        enter interactive mode after executing 'script'
  -l mod    require library 'mod' into global 'mod'
  -l g=mod  require library 'mod' into global 'g'
  -v        show version information
  -E        ignore environment variables
  -W        turn warnings on
  --        stop handling options
  -         stop handling options and execute stdin"""

def print_usage_error(msg):
    sys.stderr.write(f"{PROGNAME}: {msg}\n")
    sys.stderr.write(USAGE.format(prog=PROGNAME)+"\n")

def build_arg_table(argv, script_index):
    t=LuaTable()
    if script_index is None:
        for i,a in enumerate(argv): t.rawset(i,a)
    else:
        for i,a in enumerate(argv): t.rawset(i-script_index,a)
    return t

def format_error(e):
    src=e.source; line=e.line
    msg=e.message
    if src and line and not msg.startswith(str(src)+':'):
        return f"{src}:{line}: {msg}"
    return msg

def report_error(e, traceback=True):
    sys.stderr.write(f"{PROGNAME}: {format_error(e)}\n")
    if traceback:
        sys.stderr.write("stack traceback:\n\t[C]: in ?\n")

def run_chunk(text, source, varargs=None):
    return parse_and_run(text, Env(parent=GLOBAL_ENV), source, varargs or [])

def run_file(path, varargs=None):
    try:
        with open(path,'r',encoding='utf-8') as f: text=f.read()
    except OSError:
        raise LuaError("cannot open %s: No such file or directory" % path)
    return run_chunk(text, '@'+path, varargs or [])

def handle_init(ignore_env):
    if ignore_env: return
    val=os.environ.get('LUA_INIT_5_5')
    name='LUA_INIT_5_5'
    if val is None:
        val=os.environ.get('LUA_INIT'); name='LUA_INIT'
    if val is None: return
    if val.startswith('@'):
        run_file(val[1:], [])
    else:
        run_chunk(val, name, [])

def do_require_option(spec):
    if '=' in spec:
        glob, mod = spec.split('=',1)
    else:
        mod=spec; glob=spec.split('.')[-1]
    res=b_require([mod])
    GLOBAL_ENV.globals.rawset(glob, res[0] if res else True)

def repl():
    sys.stdout.write(VERSION_LINE+'\n')
    buf=''
    prompt='> '
    while True:
        try:
            sys.stdout.write(prompt); sys.stdout.flush()
            line=sys.stdin.readline()
            if line=='': break
            if not buf and line.startswith('='):
                line='return '+line[1:]
            buf += line
            try:
                res=run_chunk(buf, 'stdin', [])
                if res: b_print(res)
                buf=''; prompt='> '
            except LuaError as e:
                # incomplete heuristic
                if 'expected' in e.message or 'unfinished' in e.message or "near <eof>" in e.message:
                    prompt='>> '; continue
                report_error(e, False); buf=''; prompt='> '
        except (KeyboardInterrupt, EOFError):
            sys.stdout.write('\n'); break

def parse_options(argv):
    opts=[]; interactive=False; version=False; ignore_env=False; script_index=None; script_stdin=False
    i=1
    while i < len(argv):
        a=argv[i]
        if a=='--':
            i+=1
            if i < len(argv): script_index=i
            break
        if a=='-':
            script_index=i; script_stdin=True; break
        if not a.startswith('-') or a=='':
            script_index=i; break
        if a=='-i': interactive=True; opts.append(('i',None)); i+=1
        elif a=='-v': version=True; opts.append(('v',None)); i+=1
        elif a=='-E': ignore_env=True; opts.append(('E',None)); i+=1
        elif a=='-W': opts.append(('W',None)); i+=1
        elif a.startswith('-e'):
            if len(a)>2: stat=a[2:]
            else:
                if i+1>=len(argv): print_usage_error("'-e' needs argument"); sys.exit(1)
                i+=1; stat=argv[i]
            opts.append(('e',stat)); i+=1
        elif a.startswith('-l'):
            if len(a)>2: mod=a[2:]
            else:
                if i+1>=len(argv): print_usage_error("'-l' needs argument"); sys.exit(1)
                i+=1; mod=argv[i]
            opts.append(('l',mod)); i+=1
        else:
            print_usage_error("unrecognized option '%s'" % a); sys.exit(1)
    return opts, interactive, version, ignore_env, script_index, script_stdin

def main(argv):
    global PROGNAME
    PROGNAME=argv[0] if argv else './executable'
    opts, interactive, version, ignore_env, script_index, script_stdin = parse_options(argv)
    install_libs()
    GLOBAL_ENV.globals.rawset('arg', build_arg_table(argv, script_index))
    if version:
        sys.stdout.write(VERSION_LINE+'\n')
    try:
        handle_init(ignore_env)
        # execute -e/-l in order (skip other flags)
        for kind,val in opts:
            if kind=='e': run_chunk(val, '(command line)', [])
            elif kind=='l': do_require_option(val)
        if script_index is not None:
            varargs=argv[script_index+1:]
            if script_stdin:
                text=sys.stdin.read(); run_chunk(text, 'stdin', varargs)
            else:
                run_file(argv[script_index], varargs)
        else:
            has_exec=any(k in ('e','l') for k,v in opts) or version
            if interactive or (not has_exec and sys.stdin.isatty()):
                repl()
            elif not has_exec:
                text=sys.stdin.read(); run_chunk(text, 'stdin', [])
            elif interactive:
                repl()
    except SystemExit:
        raise
    except LuaError as e:
        tb = not (e.message.startswith('cannot open') or 'syntax' in e.message or 'unexpected symbol' in e.message or 'expected near' in e.message)
        report_error(e, tb)
        sys.exit(1)
    except BrokenPipeError:
        sys.exit(1)

if __name__ == '__main__':
    main(sys.argv)
